# Verify girth more carefully and check 3-colorability
n = 24
offsets = [-12, 7, -7] * 8

edges = set()
for i in range(n):
    j = (i + 1) % n
    if i < j:
        edges.add((i, j))
    else:
        edges.add((j, i))
    k = (i + offsets[i]) % n
    if i < k:
        edges.add((i, k))
    else:
        edges.add((k, i))

print("Edges:", sorted(edges))
print("Count:", len(edges))

# Verify all degrees are 3
adj = {i: [] for i in range(n)}
for u,v in edges:
    adj[u].append(v)
    adj[v].append(u)
for i in range(n):
    assert len(adj[i]) == 3, f"Degree of {i} is {len(adj[i])}"

# Verify girth with more robust BFS
from collections import deque

def girth_robust(adj, n):
    best = n + 1
    for s in range(n):
        dist = [-1] * n
        parent = [-1] * n
        q = deque([s])
        dist[s] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:  # not the edge we came from
                    # found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
        if best <= 6:
            break
    return best

g = girth_robust(adj, n)
print("Girth:", g)

# Now find a proper 3-coloring
# Use simple greedy or backtracking
colors = [-1] * n

def solve_coloring(v):
    if v == n:
        return True
    used = {colors[w] for w in adj[v] if colors[w] != -1}
    for c in range(3):
        if c not in used:
            colors[v] = c
            if solve_coloring(v + 1):
                return True
            colors[v] = -1
    return False

solve_coloring(0)
print("Colors:", colors)
print("Valid?", all(colors[u] != colors[v] for u,v in edges))
